// Serves /api/tcb1-manifest — discovery for the TCB1 binary browse
// dataset (Phase 2A, FILTER-REVAMP-DESIGN.md §12): the dataset's own
// manifest (tcb1-data/manifest.json in the repo, generated by
// scripts/build-tcb1.mjs in the same publish as the browse pages).
// The client engages the binary stream only when the manifest's
// source fingerprint equals the browse manifest's fingerprint, so a
// stale or mismatched dataset can never be picked up — the JSON
// stream remains the fallback in every doubtful case.
//
// Read pattern mirrors functions/api/browse-manifest.js: the bytes
// are pinned to the DEPLOYED commit (CF_PAGES_COMMIT_SHA) so the
// manifest always describes the dataset the same deploy carries,
// with a short SWR edge cache absorbing request volume.
const REPO = "Joshuv-AI/antarctic-labs";

function repoManifestUrl(env) {
  const sha = (env && env.CF_PAGES_COMMIT_SHA) || "main";
  return `https://raw.githubusercontent.com/${REPO}/${sha}/tcb1-data/manifest.json`;
}

export async function onRequest(context) {
  const { env } = context;
  try {
    const upstream = await fetch(repoManifestUrl(env), {
      cf: { cacheTtl: 60, cacheEverything: true },
    });
    if (!upstream.ok) {
      return new Response(JSON.stringify({ error: "tcb1 manifest unavailable" }), {
        status: 404,
        headers: { "content-type": "application/json" },
      });
    }
    const body = await upstream.text();
    // Shape check at the edge: a malformed body must read as "no
    // binary dataset", never as a half-valid manifest.
    const parsed = JSON.parse(body);
    if (
      !parsed ||
      parsed.format !== "TCB1" ||
      typeof parsed.total_records !== "number" ||
      !parsed.source ||
      typeof parsed.source.fingerprint_sha256_concat !== "string"
    ) {
      return new Response(JSON.stringify({ error: "tcb1 manifest malformed" }), {
        status: 404,
        headers: { "content-type": "application/json" },
      });
    }
    return new Response(body, {
      headers: {
        "content-type": "application/json",
        "cache-control": "public, max-age=60, stale-while-revalidate=300",
      },
    });
  } catch {
    return new Response(JSON.stringify({ error: "tcb1 manifest unavailable" }), {
      status: 404,
      headers: { "content-type": "application/json" },
    });
  }
}
